        static readonly PageSpec[] Pages={
            new PageSpec("SplashTitle",ScreenId.SplashTitle,1,false),new PageSpec("Loading",ScreenId.Loading,1,true),new PageSpec("Home",ScreenId.Home,1,true),new PageSpec("WorldMap",ScreenId.WorldMap,1,true),new PageSpec("LevelSelect",ScreenId.ChapterMap,1,true),new PageSpec("PreLevel",ScreenId.PreLevel,1,true),new PageSpec("Gameplay",ScreenId.Gameplay,1,true),new PageSpec("Pause",ScreenId.Pause,1,false),new PageSpec("Victory",ScreenId.Victory,1,true),new PageSpec("Fail",ScreenId.Fail,1,true),new PageSpec("ChapterComplete",ScreenId.ChapterComplete,1,false),new PageSpec("Dialogue",ScreenId.Dialogue,1,true),
            new PageSpec("CharacterCollection",ScreenId.Characters,2,false),new PageSpec("DailyReward",ScreenId.DailyReward,2,false),new PageSpec("Profile",ScreenId.Profile,2,false),new PageSpec("Inventory",ScreenId.Inventory,2,false),new PageSpec("Shop",ScreenId.Shop,2,true),new PageSpec("SpecialOffer",ScreenId.SpecialOffer,2,false),new PageSpec("OutOfEnergy",ScreenId.OutOfEnergy,2,false),new PageSpec("BoosterSelect",ScreenId.BoosterSelect,2,false),new PageSpec("RewardClaim",ScreenId.RewardClaim,2,false),
            new PageSpec("EventsHub",ScreenId.Events,3,false),new PageSpec("EventDetail",ScreenId.EventDetail,3,false),new PageSpec("IndividualRanking",ScreenId.IndividualRanking,3,false),new PageSpec("TeamHub",ScreenId.TeamHub,3,false),new PageSpec("TeamRanking",ScreenId.TeamRanking,3,false),new PageSpec("TeamChat",ScreenId.TeamChat,3,false),new PageSpec("FriendsList",ScreenId.FriendsList,3,false),new PageSpec("Mail",ScreenId.Mail,3,false),
            new PageSpec("Settings",ScreenId.Settings,4,false),new PageSpec("LanguageSelect",ScreenId.LanguageSelect,4,false),new PageSpec("Login",ScreenId.Login,4,false),new PageSpec("TutorialOverlay",ScreenId.TutorialOverlay,4,false),new PageSpec("OfflineState",ScreenId.OfflineState,4,false),new PageSpec("MaintenanceState",ScreenId.MaintenanceState,4,false),new PageSpec("EmptyErrorStates",ScreenId.EmptyErrorState,4,false)};
        [MenuItem("Legends of Rus/Tests/Run v1.20 Step 10.2 Final 36-Page Reconstruction Audit")]
        public static void Run(){BuildAllCandidates();var failures=new List<string>();if(Pages.Length!=36)failures.Add("Final contract list must contain 36 pages.");string contracts="Assets/LegendsOfRus/Documentation/V1_20_STEP06_PAGE_ASSET_CONTRACTS.json";if(!File.Exists(contracts)||Count(File.ReadAllText(contracts),"\"pageKey\"")!=36)failures.Add("Step 6 page contract source must contain exactly 36 pageKey entries.");if(!CheckCoverage())failures.Add("Cross-wave requirement coverage is not 254/254.");int sourceReady=0,approved=0,active=0;var csv=new StringBuilder("index,pageKey,screenId,wave,sourceCandidate,unityRuntimeEvidence,directApprovedReference,activeProductionRoute,cutoverEligibility\n");for(int i=0;i<Pages.Length;i++){PageSpec p=Pages[i];string prefab=CandidatePath(p);bool candidate=AssetDatabase.LoadAssetAtPath<GameObject>(prefab)!=null;if(candidate)sourceReady++;else failures.Add("Missing candidate prefab for "+p.pageKey+": "+prefab);bool runtime=WaveRuntimeEvidence(p.wave);bool direct=p.directApprovedReference&&ApprovedReferenceExists(p.id);if(direct)approved++;bool isActive=ProductionCoreLoopPageRegistry.IsCutover(p.id)||ProductionMetaPageCutoverRegistry.IsCutover(p.id);if(isActive)active++;string eligible=(direct&&runtime)?"EVIDENCE_READY_NOT_AUTO_CUTOVER":"BLOCKED_OR_PENDING";csv.Append(i).Append(',').Append(p.pageKey).Append(',').Append(p.id).Append(',').Append(p.wave).Append(',').Append(candidate).Append(',').Append(runtime).Append(',').Append(direct).Append(',').Append(isActive).Append(',').Append(eligible).AppendLine();}
            int runtimeWaves=(WaveRuntimeEvidence(1)?1:0)+(WaveRuntimeEvidence(2)?1:0)+(WaveRuntimeEvidence(3)?1:0)+(WaveRuntimeEvidence(4)?1:0);int runtimePages=(WaveRuntimeEvidence(1)?12:0)+(WaveRuntimeEvidence(2)?9:0)+(WaveRuntimeEvidence(3)?8:0)+(WaveRuntimeEvidence(4)?7:0);string decision=failures.Count>0?"FAIL_SOURCE_RECONSTRUCTION_AUDIT":(sourceReady==36?"PASS_36_OF_36_SOURCE_RECONSTRUCTION_RUNTIME_REFERENCE_ACCEPTANCE_SEPARATE":"FAIL_SOURCE_RECONSTRUCTION_AUDIT");Write(sourceReady,runtimePages,runtimeWaves,approved,active,decision,failures,csv.ToString());if(failures.Count>0)throw new InvalidOperationException(string.Join(Environment.NewLine,failures.ToArray()));Debug.Log("v1.20 Step 10.2 final 36-page audit PASS: source candidates="+sourceReady+"/36, requirements=254/254, runtime-evidenced pages="+runtimePages+"/36, direct approved refs="+approved+"/36, currently active routes="+active+". Source reconstruction complete; runtime/reference/cutover acceptance remains separate.");if(!Application.isBatchMode)EditorUtility.DisplayDialog("Legends of Rus","Final 36-page source reconstruction audit PASS: 36/36 candidates and 254/254 requirements. See the generated audit matrix for runtime/reference/cutover status.","OK");}
        static void BuildAllCandidates(){if(Step20ProductionAssetWave01PrefabBuilder.NeedsBuild())Step20ProductionAssetWave01PrefabBuilder.BuildAll(false);if(Step20ProductionAssetWave02PrefabBuilder.NeedsBuild())Step20ProductionAssetWave02PrefabBuilder.BuildAll(false);if(Step20ProductionAssetWave03PrefabBuilder.NeedsBuild())Step20ProductionAssetWave03PrefabBuilder.BuildAll(false);if(Step20ProductionAssetWave04PrefabBuilder.NeedsBuild())Step20ProductionAssetWave04PrefabBuilder.BuildAll(false);}
        static bool CheckCoverage(){string w1="Assets/LegendsOfRus/Documentation/V1_20_STEP07_WAVE01_ASSET_MANIFEST.json",w2="Assets/LegendsOfRus/Documentation/V1_20_STEP08_WAVE02_REQUIREMENT_COVERAGE.json",w3="Assets/LegendsOfRus/Documentation/V1_20_STEP09_WAVE03_REQUIREMENT_COVERAGE.json",w4="Assets/LegendsOfRus/Documentation/V1_20_STEP10_WAVE04_REQUIREMENT_COVERAGE.json";if(!File.Exists(w1)||!File.Exists(w2)||!File.Exists(w3)||!File.Exists(w4))return false;string a=File.ReadAllText(w1),b=File.ReadAllText(w2),c=File.ReadAllText(w3),d=File.ReadAllText(w4);return a.IndexOf("\"requirementCount\": 92",StringComparison.Ordinal)>=0&&a.IndexOf("100% candidate mapped",StringComparison.Ordinal)>=0&&b.IndexOf("\"assetRequirementCount\": 65",StringComparison.Ordinal)>=0&&b.IndexOf("\"coveredRequirementCount\": 65",StringComparison.Ordinal)>=0&&c.IndexOf("\"requirementCount\": 56",StringComparison.Ordinal)>=0&&c.IndexOf("\"coveredCount\": 56",StringComparison.Ordinal)>=0&&d.IndexOf("\"covered\": 41",StringComparison.Ordinal)>=0&&d.IndexOf("\"total\": 41",StringComparison.Ordinal)>=0;}
        static string CandidatePath(PageSpec p){string root=p.wave==1?Step20ProductionAssetWave01PrefabBuilder.CandidateRoot:p.wave==2?Step20ProductionAssetWave02PrefabBuilder.CandidateRoot:p.wave==3?Step20ProductionAssetWave03PrefabBuilder.CandidateRoot:Step20ProductionAssetWave04PrefabBuilder.CandidateRoot;return root+"/"+p.id+".prefab";}
        static bool WaveRuntimeEvidence(int wave){string path=wave==1?"ProjectDocs/V1_20_STEP07_4/UnityRuntimeCaptures/UNITY_RUNTIME_CAPTURE_EXECUTED.json":wave==2?"ProjectDocs/V1_20_STEP08_4/UnityRuntimeCaptures/UNITY_RUNTIME_CAPTURE_EXECUTED.json":wave==3?"ProjectDocs/V1_20_STEP09_4/RuntimeEvidence/UNITY_RUNTIME_CAPTURE_EXECUTED.json":"ProjectDocs/V1_20_STEP10_2/RuntimeEvidence/UNITY_RUNTIME_CAPTURE_EXECUTED.json";int expected=wave==1?48:wave==2?36:wave==3?32:28;return File.Exists(path)&&File.ReadAllText(path).IndexOf("\"captures\": "+expected,StringComparison.Ordinal)>=0;}
        static bool ApprovedReferenceExists(ScreenId id){string name=id.ToString();if(id==ScreenId.ChapterMap)name="ChapterMap";return File.Exists("Assets/LegendsOfRus/Art/ReferenceOnly/ApprovedScreens/"+name+".png");}
        static int Count(string s,string token){int c=0,p=0;while((p=s.IndexOf(token,p,StringComparison.Ordinal))>=0){c++;p+=token.Length;}return c;}
        static void Write(int sourceReady,int runtimePages,int runtimeWaves,int approved,int active,string decision,List<string> failures,string csv){string json="{\n  \"schemaVersion\": 1,\n  \"milestone\": \"v1.20-step10.2-final-36-page-reconstruction-audit\",\n  \"decision\": \""+decision+"\",\n  \"functionalPageContracts\": 36,\n  \"sourceCandidatePages\": "+sourceReady+",\n  \"assetRequirementsTotal\": 254,\n  \"assetRequirementsCovered\": 254,\n  \"runtimeEvidenceWaves\": "+runtimeWaves+",\n  \"runtimeEvidencePages\": "+runtimePages+",\n  \"directApprovedReferencePages\": "+approved+",\n  \"activeProductionRoutes\": "+active+",\n  \"sourceReconstructionCompleteMeansRuntimeApproved\": false,\n  \"sourceReconstructionCompleteMeansReferenceApproved\": false,\n  \"sourceReconstructionCompleteMeansCutoverApproved\": false,\n  \"failureCount\": "+failures.Count+"\n}\n";string abs=Abs(Output);Directory.CreateDirectory(Path.GetDirectoryName(abs));File.WriteAllText(abs,json);File.WriteAllText(Abs(Csv),csv);AssetDatabase.Refresh();}
        static string Abs(string p){return Path.Combine(Directory.GetCurrentDirectory(),p.Replace('/',Path.DirectorySeparatorChar));}
